/**
Generate a URL for querying user info based on a given API URL and a user ID. The expected URL for query should be the API URL concatenated with the user ID. If the user ID is empty or invalid, the function should return None so that no query will be made.
Examples:
- get_url_for_query("https://example.com/api/user", "aBc123") returns 'https://example.com/api/user/aBc123'
- get_url_for_query("https://example.com/api/user", "") returns NULL

@param api_url: The API URL to query user info.
@param user_id: The user ID to query.

@return The URL for query. If the user ID is empty or invalid, return NULL.
*/
char* get_url_for_query(const char* api_url, const char* user_id) {
    // Validate inputs: api_url must not be NULL, user_id must not be NULL or empty.
    // Checking api_url for NULL prevents a segmentation fault from strlen(api_url).
    if (api_url == NULL || user_id == NULL || strlen(user_id) == 0) {
        return NULL;
    }

    size_t api_url_len = strlen(api_url);
    size_t user_id_len = strlen(user_id);

    // Determine if a '/' needs to be added between api_url and user_id.
    // If api_url is not empty and its last character is '/', we should not add another one
    // to avoid double slashes (e.g., "api/user//id").
    int needs_slash = 1; // Assume we need a slash by default
    if (api_url_len > 0 && api_url[api_url_len - 1] == '/') {
        needs_slash = 0; // No slash needed if api_url already ends with one
    }

    // Calculate the required length for the new URL string:
    // length of api_url + (1 for '/' if needed, else 0) + length of user_id + 1 for null terminator
    size_t total_len = api_url_len + (needs_slash ? 1 : 0) + user_id_len + 1;

    // Allocate memory for the new URL string
    char* query_url = (char*)malloc(total_len);
    if (query_url == NULL) {
        // Memory allocation failed
        return NULL;
    }

    // Construct the URL safely using snprintf to prevent buffer overflows.
    // The format string depends on whether a slash needs to be inserted.
    int written;
    if (needs_slash) {
        written = snprintf(query_url, total_len, "%s/%s", api_url, user_id);
    } else {
        written = snprintf(query_url, total_len, "%s%s", api_url, user_id);
    }

    // Check if snprintf encountered an error or if the output was truncated.
    // A return value < 0 indicates an encoding error.
    // A return value >= total_len indicates truncation (buffer was too small).
    // With our precise total_len calculation, truncation should not occur unless
    // the input strings themselves were not properly null-terminated, which strlen
    // would have miscalculated, or if an encoding error occurred.
    if (written < 0 || (size_t)written >= total_len) {
        free(query_url); // Free the allocated memory on failure
        return NULL;     // Indicate failure
    }

    return query_url;
}
